(641938, 66979, 10686, '<td valign="top">A different colored ball would help</td>', 'A different colored ball would help', '2004-03-29 01:10:25.000000', NULL, 1),
(641939, 67177, 327, '<td valign="top">Nice one, like the vivid colors. Nice focus work.</td>', 'Nice one, like the vivid colors. Nice focus work.', '2004-03-29 01:10:49.000000', NULL, 1),
