(642101, 67161, 15407, '<td valign="top">phill (slow) downhill (fast) fast - good job!</td>', 'phill (slow) downhill (fast) fast - good job!', '2004-03-29 02:58:40.000000', NULL, 1),
(642103, 66979, 15407, '<td valign="top">Great Work ... I''m sure it was caught !</td>', 'Great Work ... I''m sure it was caught !', '2004-03-29 03:00:31.000000', NULL, 1),
(642104, 67123, 15511, '<td valign="top">Editing is a bit obvious. Insufficient motion.</td>', 'Editing is a bit obvious. Insufficient motion.', '2004-03-29 03:00:33.000000', NULL, 1),
