(642168, 67051, 18552, '<td valign="top">Your picture is wonderful. The motion blur turned out really well and enhances the subject matter perfectly!</td>', 'Your picture is wonderful. The motion blur turned out really well and enhances the subject matter perfectly!', '2004-03-29 05:04:32.000000', NULL, 1),
