(642399, 66425, 4338, '<td valign="top">excelent, I love the colors and you did an awesome job at the zoom blur!!!</td>', 'excelent, I love the colors and you did an awesome job at the zoom blur!!!', '2004-03-29 10:50:05.000000', NULL, 1),
