(642662, 67134, 16957, '<td valign="top">A nice photo but evidence of motion is hard to see at first glance as is the subject that is in motion.</td>', 'A nice photo but evidence of motion is hard to see at first glance as is the subject that is in motion.', '2004-03-29 15:02:18.000000', NULL, 1),
(642666, 66985, 16957, '<td valign="top">My top pic of the challenge. Clean, nice lines and the green sets off the silver/black and white beautifully. VW not as sharp as it could be but hey - I can''t do any better!</td>', 'My top pic of the challenge. Clean, nice lines and the green sets off the silver/black and white beautifully. VW not as sharp as it could be but hey - I can''t do any better!', '2004-03-29 15:03:22.000000', NULL, 1),
(642668, 66638, 16957, '<td valign="top">Nice composition. A pity we can''t see any of the subjects that are moving but a authentic feeling of motion nonetheless.</td>', 'Nice composition. A pity we can''t see any of the subjects that are moving but a authentic feeling of motion nonetheless.', '2004-03-29 15:04:18.000000', NULL, 1),
(642721, 67143, 656, '<td valign="top">good example of panning technique.  Image doesn''t quite have enough interest to get a really high mark but you''ve got the base technique down well.</td>', 'good example of panning technique.  Image doesn''t quite have enough interest to get a really high mark but you''ve got the base technique down well.', '2004-03-29 15:38:24.000000', NULL, 1),
(642722, 66979, 4008, '<td valign="top">Great idea, what a concentration that dog is showing. Would be more suitable for a portrait format, so with some parts of the side cropped away.</td>', 'Great idea, what a concentration that dog is showing. Would be more suitable for a portrait format, so with some parts of the side cropped away.', '2004-03-29 15:38:51.000000', NULL, 1),
(642723, 66970, 656, '<td valign="top">I love the flow and movement through the shot.  The colours work together well too.</td>', 'I love the flow and movement through the shot.  The colours work together well too.', '2004-03-29 15:38:51.000000', NULL, 1),
(642724, 67161, 656, '<td valign="top">good use of two subjects travelling in opposite directions to really emphasise the pan.  Main subject isn''t quite sharp though, but a good effort.</td>', 'good use of two subjects travelling in opposite directions to really emphasise the pan.  Main subject isn''t quite sharp though, but a good effort.', '2004-03-29 15:39:24.000000', NULL, 1),
(642725, 67050, 4008, '<td valign="top">Some great panning you did here. I like the greytones in this image, fits well together.</td>', 'Some great panning you did here. I like the greytones in this image, fits well together.', '2004-03-29 15:39:42.000000', NULL, 1),
(642726, 67089, 656, '<td valign="top">Certainly plenty of motion going on</td>', 'Certainly plenty of motion going on', '2004-03-29 15:39:43.000000', NULL, 1),
(642728, 67165, 656, '<td valign="top">Excellent motion - would have loved it a touch earlier to see the ball streaking out of the shot too.  Seems quite dark/ underexposed maybe by a stop or so ?</td>', 'Excellent motion - would have loved it a touch earlier to see the ball streaking out of the shot too.  Seems quite dark/ underexposed maybe by a stop or so ?', '2004-03-29 15:40:18.000000', NULL, 1),
(642729, 67072, 656, '<td valign="top">I can almost hear it - great shot.  Some more dramatic lighting or a better location would enhance this further, but good as it is.</td>', 'I can almost hear it - great shot.  Some more dramatic lighting or a better location would enhance this further, but good as it is.', '2004-03-29 15:40:51.000000', NULL, 1),
(642731, 66914, 656, '<td valign="top">I don''t really see any motion happening in this shot ?</td>', 'I don''t really see any motion happening in this shot ?', '2004-03-29 15:41:24.000000', NULL, 1),
(642732, 66970, 14614, '<td valign="top">mavelous colors and feel -- one of my favorites</td>', 'mavelous colors and feel -- one of my favorites', '2004-03-29 15:41:37.000000', NULL, 1),
(642735, 66669, 656, '<td valign="top">Good pan - a fraction earlier would maybe have shown what looks like a relay exchange as it happened and made for a stronger shot ?</td>', 'Good pan - a fraction earlier would maybe have shown what looks like a relay exchange as it happened and made for a stronger shot ?', '2004-03-29 15:42:25.000000', NULL, 1),
(642737, 67027, 656, '<td valign="top">A good attempt - the main subject could be sharper maybe, but it certainly adds a lot to the drama of the scene than if it was all perfectly stopped.</td>', 'A good attempt - the main subject could be sharper maybe, but it certainly adds a lot to the drama of the scene than if it was all perfectly stopped.', '2004-03-29 15:43:25.000000', NULL, 1),
(642738, 66963, 656, '<td valign="top">I don''t really see much blurred action here - the shot is extremely dark too.</td>', 'I don''t really see much blurred action here - the shot is extremely dark too.', '2004-03-29 15:43:51.000000', NULL, 1),
(642739, 66985, 12962, '<td valign="top">Nice.  Car and driver are well focused in this panning.  It seems like the car is not moving at all!  Composition is harmonious ... I like it that you had the car on one side and have some space in the other side to suggest that there is room for the car to move ... and fast!  Good job</td>', 'Nice.  Car and driver are well focused in this panning.  It seems like the car is not moving at all!  Composition is harmonious ... I like it that you had the car on one side and have some space in the other side to suggest that there is room for the car to move ... and fast!  Good job', '2004-03-29 15:43:59.000000', NULL, 1),
(642740, 67174, 656, '<td valign="top">I don''t see any motion blur here ?</td>', 'I don''t see any motion blur here ?', '2004-03-29 15:44:09.000000', NULL, 1),
(642741, 67179, 656, '<td valign="top">Good blur and sharp subject - on a string ?</td>', 'Good blur and sharp subject - on a string ?', '2004-03-29 15:44:30.000000', NULL, 1),
(642742, 67090, 656, '<td valign="top">Very dramatic!</td>', 'Very dramatic!', '2004-03-29 15:44:43.000000', NULL, 1),
(642744, 67050, 656, '<td valign="top">Grey, grey and more grey!  Seems like a good candidate for B&amp;W treatment.</td>', 'Grey, grey and more grey!  Seems like a good candidate for B&W treatment.', '2004-03-29 15:45:13.000000', NULL, 1),
(642746, 67051, 11570, '<td valign="top">Not sure whetehr you PPed it to get such an amazing point of focus ~ the the dog''s eye.  But this was well seen and executed a 9</td>', 'Not sure whetehr you PPed it to get such an amazing point of focus ~ the the dog''s eye.  But this was well seen and executed a 9', '2004-03-29 15:45:38.000000', NULL, 1),
(642750, 67040, 656, '<td valign="top">Quite a set up I''m sure.  Works well, though maybe more colourful pegs could enhance ?</td>', 'Quite a set up I''m sure.  Works well, though maybe more colourful pegs could enhance ?', '2004-03-29 15:47:04.000000', NULL, 1),
(642752, 67162, 11570, '<td valign="top">An interesting idea nicely setup ~ for the overall subject lacks a certain wow factor compared to some of the others here. a 7</td>', 'An interesting idea nicely setup ~ for the overall subject lacks a certain wow factor compared to some of the others here. a 7', '2004-03-29 15:47:14.000000', NULL, 1),
(642755, 67039, 656, '<td valign="top">Great idea.</td>', 'Great idea.', '2004-03-29 15:48:06.000000', NULL, 1),
(642758, 66966, 656, '<td valign="top">Good demonstration of panning, but the subject isn''t very interesting.</td>', 'Good demonstration of panning, but the subject isn''t very interesting.', '2004-03-29 15:48:59.000000', NULL, 1),
(642761, 67024, 11570, '<td valign="top">Caught the right shutter speed for motion blur rather than milky waters.<br/> <br/>There are IMHO some stronger Motion Blur images here an 8</td>', 'Caught the right shutter speed for motion blur rather than milky waters. There are IMHO some stronger Motion Blur images here an 8', '2004-03-29 15:49:31.000000', NULL, 1),
(642763, 66927, 656, '<td valign="top">Good motion the butterfly.  The background really needs some more attention though, as it distracts, especially with the hot spots in the upper left</td>', 'Good motion the butterfly.  The background really needs some more attention though, as it distracts, especially with the hot spots in the upper left', '2004-03-29 15:50:29.000000', NULL, 1),
(642765, 67177, 656, '<td valign="top">Somehow the colours have ended up looking rather sick :)  Good motion shot though.</td>', 'Somehow the colours have ended up looking rather sick :)  Good motion shot though.', '2004-03-29 15:51:22.000000', NULL, 1),
(642768, 66934, 656, '<td valign="top">Strong, graphic subjects work well on this technique - as you''ve shown here.</td>', 'Strong, graphic subjects work well on this technique - as you''ve shown here.', '2004-03-29 15:52:04.000000', NULL, 1),
(642769, 66899, 11570, '<td valign="top">Motion blur nicely interpreted but I also think it is just that bit OOF &amp; though they may have been running uphill I would have prefered a level "horizon".</td>', 'Motion blur nicely interpreted but I also think it is just that bit OOF & though they may have been running uphill I would have prefered a level "horizon".', '2004-03-29 15:52:33.000000', NULL, 1),
(642770, 67007, 656, '<td valign="top">Yup, its in motion, but subject isn''t very interesting.</td>', 'Yup, its in motion, but subject isn''t very interesting.', '2004-03-29 15:53:12.000000', NULL, 1),
(642771, 67082, 656, '<td valign="top">I like the twist and zoom effect - playing havoc with my eyes though.  The yellow handle is particularly effective at grounding the shot.</td>', 'I like the twist and zoom effect - playing havoc with my eyes though.  The yellow handle is particularly effective at grounding the shot.', '2004-03-29 15:54:06.000000', NULL, 1),
(642774, 67062, 656, '<td valign="top">I like it - enough mystery to make it interesting - what''s he pulling, where is he going, and so on.  The blocked up composition against the side/ exiting the frame furthers that feel.  Good entry (9)</td>', 'I like it - enough mystery to make it interesting - what''s he pulling, where is he going, and so on.  The blocked up composition against the side/ exiting the frame furthers that feel.  Good entry (9)', '2004-03-29 15:55:16.000000', NULL, 1),
(642775, 67136, 656, '<td valign="top">Yup, it is a flag and it is in motion.  But not very interesting.</td>', 'Yup, it is a flag and it is in motion.  But not very interesting.', '2004-03-29 15:55:45.000000', NULL, 1),
(642777, 66983, 656, '<td valign="top">The slight shadow under the left bird works, for some reason :)  Interesting.</td>', 'The slight shadow under the left bird works, for some reason :)  Interesting.', '2004-03-29 15:56:26.000000', NULL, 1),
(642778, 67156, 11570, '<td valign="top">Combination of EL wire (neon string) and spring flowers.  Nicely thought up and executed but for me it does not impart Motion Blur.  If the flowers were sharper and the EL wire OOF maybe a hint would have been there ~ sorry a 4</td>', 'Combination of EL wire (neon string) and spring flowers.  Nicely thought up and executed but for me it does not impart Motion Blur.  If the flowers were sharper and the EL wire OOF maybe a hint would have been there ~ sorry a 4', '2004-03-29 15:57:52.000000', NULL, 1),
(642779, 66984, 656, '<td valign="top">Very crisp, good technique and capture</td>', 'Very crisp, good technique and capture', '2004-03-29 15:58:05.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(642780, 67074, 10869, '<td valign="top">You shouldn''t have cut the wheels...</td>', 'You shouldn''t have cut the wheels...', '2004-03-29 15:58:14.000000', NULL, 1),
(642783, 67016, 656, '<td valign="top">A bit more space to the left would give him somwhere to go - but you''ve got all the shadow as well.</td>', 'A bit more space to the left would give him somwhere to go - but you''ve got all the shadow as well.', '2004-03-29 15:58:52.000000', NULL, 1),
(642785, 67080, 656, '<td valign="top">A bit more attention to framing/ composition could help with this - a good subject but it looks like its about to fall over.  Even if it is, it ends up disconcerting.</td>', 'A bit more attention to framing/ composition could help with this - a good subject but it looks like its about to fall over.  Even if it is, it ends up disconcerting.', '2004-03-29 16:01:28.000000', NULL, 1),
(642786, 67112, 656, '<td valign="top">Looks like it might be good, but it is too small to tell.</td>', 'Looks like it might be good, but it is too small to tell.', '2004-03-29 16:01:44.000000', NULL, 1),
(642787, 66870, 12962, '<td valign="top">Spooky!  Very well thought of, very original.  Off center subject works well.  A suggestion of monochrome also is very appealing.  And finally, the lighting from the side adds to the eerie effect.</td>', 'Spooky!  Very well thought of, very original.  Off center subject works well.  A suggestion of monochrome also is very appealing.  And finally, the lighting from the side adds to the eerie effect.', '2004-03-29 16:01:58.000000', NULL, 1),
