(643562, 66970, 4008, '<td valign="top">I like the graphic, almost abstract style and colors of this image.</td>', 'I like the graphic, almost abstract style and colors of this image.', '2004-03-30 06:52:31.000000', NULL, 1),
(643564, 66053, 4008, '<td valign="top">I don''t feel the movement blur here enhances the subject, rather makes it worse.</td>', 'I don''t feel the movement blur here enhances the subject, rather makes it worse.', '2004-03-30 06:57:08.000000', NULL, 1),
