(643576, 67027, 4008, '<td valign="top">Here the motion blur works really well in my opinion. Really enhances the action, while keeping the main subject recognisable. Good composition as well. Best sports shot in this challenge.</td>', 'Here the motion blur works really well in my opinion. Really enhances the action, while keeping the main subject recognisable. Good composition as well. Best sports shot in this challenge.', '2004-03-30 07:11:14.000000', NULL, 1),
(643577, 67177, 4008, '<td valign="top">Attractive colors, maybe a bit oversaturated, but it works well here. Simple composition keeps the blur acceptable, i.e. it contributes here, does not bring the image down.</td>', 'Attractive colors, maybe a bit oversaturated, but it works well here. Simple composition keeps the blur acceptable, i.e. it contributes here, does not bring the image down.', '2004-03-30 07:13:17.000000', NULL, 1),
