(643583, 67059, 4008, '<td valign="top">Could have done with some more empty space around it, and the cart more to the left, to add some more dynamic feeling to it.</td>', 'Could have done with some more empty space around it, and the cart more to the left, to add some more dynamic feeling to it.', '2004-03-30 07:21:41.000000', NULL, 1),
