(643865, 67047, 9668, '<td valign="top">Nice frozen action. Background is distacting though. Unfortunate that there is a car there. Good color</td>', 'Nice frozen action. Background is distacting though. Unfortunate that there is a car there. Good color', '2004-03-30 12:40:57.000000', NULL, 1),
(643869, 67027, 16850, '<td valign="top">Tighter left crop to get rid of the foot?</td>', 'Tighter left crop to get rid of the foot?', '2004-03-30 12:42:04.000000', NULL, 1),
(643874, 67162, 16478, '<td valign="top">Nice shot. Captured the movement perfectly and the spices etc work really well in the background</td>', 'Nice shot. Captured the movement perfectly and the spices etc work really well in the background', '2004-03-30 12:50:04.000000', NULL, 1),
(643876, 67163, 16478, '<td valign="top">One of the best. The stillness of the background contrasts brilliantly with the movement of the person. Well done</td>', 'One of the best. The stillness of the background contrasts brilliantly with the movement of the person. Well done', '2004-03-30 12:51:13.000000', NULL, 1),
(643877, 67051, 16478, '<td valign="top">Great idea and really well executed. Love the expression on the face of the dog! One of the best</td>', 'Great idea and really well executed. Love the expression on the face of the dog! One of the best', '2004-03-30 12:51:39.000000', NULL, 1),
(643879, 67040, 16478, '<td valign="top">Odd idea. Would be interested to hear how (and why!) you did this? Still a nice shot, especially the choice of tones</td>', 'Odd idea. Would be interested to hear how (and why!) you did this? Still a nice shot, especially the choice of tones', '2004-03-30 12:52:36.000000', NULL, 1),
(643884, 67047, 17550, '<td valign="top">Good photograph, but the background takes away from it. If it had been taken with a scenic background it would do a lot better....</td>', 'Good photograph, but the background takes away from it. If it had been taken with a scenic background it would do a lot better....', '2004-03-30 13:02:05.000000', NULL, 1),
(643887, 67063, 17550, '<td valign="top">Very interesting shot! The colour contrast is great.</td>', 'Very interesting shot! The colour contrast is great.', '2004-03-30 13:02:48.000000', NULL, 1),
(643890, 67027, 772, '<td valign="top">This is another good example of panning motion, but the composition is suffering because of the framing... The feet are providing the motion in this photo and they are not visible... I think a wider angle could improve this idea significantly. = 5</td>', 'This is another good example of panning motion, but the composition is suffering because of the framing... The feet are providing the motion in this photo and they are not visible... I think a wider angle could improve this idea significantly. = 5', '2004-03-30 13:04:42.000000', NULL, 1),
(643892, 67142, 772, '<td valign="top">I like the natural light element of this photo.  Subjectively, it doesn''t give me much inspiration. = 4</td>', 'I like the natural light element of this photo.  Subjectively, it doesn''t give me much inspiration. = 4', '2004-03-30 13:05:39.000000', NULL, 1),
(643896, 66289, 772, '<td valign="top">I can''t seem to grab the theme presented here.  = 4</td>', 'I can''t seem to grab the theme presented here.  = 4', '2004-03-30 13:07:12.000000', NULL, 1),
(643897, 66914, 17550, '<td valign="top">What a creative shot!</td>', 'What a creative shot!', '2004-03-30 13:07:18.000000', NULL, 1),
