(643901, 66966, 772, '<td valign="top">Good pan... the composition is just too tight though.  The truck feels squeezed into the frame and there is little room for motion... = 5</td>', 'Good pan... the composition is just too tight though.  The truck feels squeezed into the frame and there is little room for motion... = 5', '2004-03-30 13:08:27.000000', NULL, 1),
(643904, 66425, 772, '<td valign="top">beautiful use of color... perfect execution... = 10</td>', 'beautiful use of color... perfect execution... = 10', '2004-03-30 13:09:11.000000', NULL, 1),
(643911, 66914, 5491, '<td valign="top">Decent photo but I don''t see how it''s a motion blur?</td>', 'Decent photo but I don''t see how it''s a motion blur?', '2004-03-30 13:12:39.000000', NULL, 1),
(643915, 66449, 5491, '<td valign="top">The grass at the bottom seems out of place.</td>', 'The grass at the bottom seems out of place.', '2004-03-30 13:13:53.000000', NULL, 1),
(643920, 67117, 772, '<td valign="top">Nice capture and composition... feels like a late afternoon scene after all the people have gone home from the park :) = 7</td>', 'Nice capture and composition... feels like a late afternoon scene after all the people have gone home from the park :) = 7', '2004-03-30 13:18:54.000000', NULL, 1),
(643923, 67134, 772, '<td valign="top">Nice urban landscape...  = 6</td>', 'Nice urban landscape...  = 6', '2004-03-30 13:20:57.000000', NULL, 1),
(643925, 66882, 772, '<td valign="top">I love watching the ducks come in for landings.. I have positioned myself over and over again trying to photograph them as they touch down with little success... = 6</td>', 'I love watching the ducks come in for landings.. I have positioned myself over and over again trying to photograph them as they touch down with little success... = 6', '2004-03-30 13:21:46.000000', NULL, 1),
(643926, 67162, 772, '<td valign="top">This makes me hungry :)  Nice work... = 7</td>', 'This makes me hungry :)  Nice work... = 7', '2004-03-30 13:22:19.000000', NULL, 1),
