(643932, 66979, 772, '<td valign="top">Nice work... I think a tall vertical composition would do well here also... and a little more open room at the bottom :) = 6</td>', 'Nice work... I think a tall vertical composition would do well here also... and a little more open room at the bottom :) = 6', '2004-03-30 13:23:40.000000', NULL, 1),
(643936, 66927, 772, '<td valign="top">Nice composition... the background is a bit distracting and contrasty but that is probably out of your control... = 5</td>', 'Nice composition... the background is a bit distracting and contrasty but that is probably out of your control... = 5', '2004-03-30 13:25:48.000000', NULL, 1),
