INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(644561, 67124, 18748, '<td valign="top">Love it. So simple and nice, makes me come back to it all the time.</td>', 'Love it. So simple and nice, makes me come back to it all the time.', '2004-03-30 22:52:02.000000', NULL, 1),
(644563, 67145, 18748, '<td valign="top">Very interesting effect. Looks like the image is moving all the time.</td>', 'Very interesting effect. Looks like the image is moving all the time.', '2004-03-30 22:53:05.000000', NULL, 1),
(644566, 67177, 18748, '<td valign="top">Good colors, great capture of motion. By the way, it is really brave of you to put word "sunset" in title.:)</td>', 'Good colors, great capture of motion. By the way, it is really brave of you to put word "sunset" in title.:)', '2004-03-30 22:54:50.000000', NULL, 1),
(644605, 67072, 13897, '<td valign="top">Really nice work. Great idea and execution.</td>', 'Really nice work. Great idea and execution.', '2004-03-30 23:55:22.000000', NULL, 1),
(644609, 66951, 13897, '<td valign="top">This should do very well for you. I hope that''s a sponge and not a blule brick...lol.</td>', 'This should do very well for you. I hope that''s a sponge and not a blule brick...lol.', '2004-03-30 23:56:45.000000', NULL, 1),
(644611, 67165, 13897, '<td valign="top">Nice work. I like the DOF and the mostly blury subject. One of the best of the group.</td>', 'Nice work. I like the DOF and the mostly blury subject. One of the best of the group.', '2004-03-30 23:58:01.000000', NULL, 1),
(644624, 67179, 18689, '<td valign="top">Great Lighting and Timing!</td>', 'Great Lighting and Timing!', '2004-03-31 00:24:57.000000', NULL, 1),
(644628, 67003, 14012, '<td valign="top">tough shot, very well done</td>', 'tough shot, very well done', '2004-03-31 00:35:54.000000', NULL, 1),
(644633, 66049, 14012, '<td valign="top">sorry, the selective desaturation doesn''t really work with this shot, IMHO. I also think it would have been better if the background subjects were still, with the motion blur on the front subject. The way it is, it just looks like camera shake.</td>', 'sorry, the selective desaturation doesn''t really work with this shot, IMHO. I also think it would have been better if the background subjects were still, with the motion blur on the front subject. The way it is, it just looks like camera shake.', '2004-03-31 00:40:17.000000', NULL, 1),
(644635, 67018, 14012, '<td valign="top">sorry, there is really no blur, that I can see.</td>', 'sorry, there is really no blur, that I can see.', '2004-03-31 00:43:17.000000', NULL, 1),
(644639, 67034, 14012, '<td valign="top">nice capture. Your white are just a bit blown out though</td>', 'nice capture. Your white are just a bit blown out though', '2004-03-31 00:45:28.000000', NULL, 1),
(644642, 67112, 14012, '<td valign="top">looks like it is a good pan shot, but your image is way too small. Will have to vote it lower because I can not see any detail. Sorry</td>', 'looks like it is a good pan shot, but your image is way too small. Will have to vote it lower because I can not see any detail. Sorry', '2004-03-31 00:47:57.000000', NULL, 1),
(644648, 67039, 14012, '<td valign="top">neat idea. Picture seems grainy and the edges are jagged though</td>', 'neat idea. Picture seems grainy and the edges are jagged though', '2004-03-31 00:51:15.000000', NULL, 1),
(644660, 67145, 14012, '<td valign="top">wow..this makes me dizzy. :)  Executed very well.</td>', 'wow..this makes me dizzy. :)  Executed very well.', '2004-03-31 00:58:49.000000', NULL, 1),
(644662, 67080, 14012, '<td valign="top">I think a different crop would have looked better. nice capture though</td>', 'I think a different crop would have looked better. nice capture though', '2004-03-31 00:59:46.000000', NULL, 1),
(644683, 66824, 19251, '<td valign="top">Holy movement Batman!</td>', 'Holy movement Batman!', '2004-03-31 01:10:39.000000', NULL, 1),
(644743, 66449, 5318, '<td valign="top">This is one of the best I''ve seen! Weeeee.Youv''e done very well in keeping the subject''s face free of blurring,and everything else is moving. Fit''s the challenge. Big 10 here!!!</td>', 'This is one of the best I''ve seen! Weeeee.Youv''e done very well in keeping the subject''s face free of blurring,and everything else is moving. Fit''s the challenge. Big 10 here!!!', '2004-03-31 01:30:21.000000', NULL, 1),
(645045, 67031, 6130, '<td valign="top">Funny and good.</td>', 'Funny and good.', '2004-03-31 05:27:00.000000', NULL, 1),
(645046, 67062, 6130, '<td valign="top">I like it.</td>', 'I like it.', '2004-03-31 05:27:26.000000', NULL, 1),
(645067, 67133, 8139, '<td valign="top">Movements well captured, nice colors. The white strokes are a bit overburned.<br/>Good overall result.</td>', 'Movements well captured, nice colors. The white strokes are a bit overburned.Good overall result.', '2004-03-31 06:20:04.000000', NULL, 1),
(645105, 67024, 9073, '<td valign="top">For the water to be truly silky, you needed to use a longer shutter speed.</td>', 'For the water to be truly silky, you needed to use a longer shutter speed.', '2004-03-31 07:32:12.000000', NULL, 1),
(645110, 66151, 9073, '<td valign="top">I''ll give an extra vote for the bad puns.</td>', 'I''ll give an extra vote for the bad puns.', '2004-03-31 07:37:51.000000', NULL, 1),
(645143, 66970, 16478, '<td valign="top">Surreal, but a really interesting photo. I like it</td>', 'Surreal, but a really interesting photo. I like it', '2004-03-31 08:25:40.000000', NULL, 1),
(645268, 67047, 888, '<td valign="top">well taken, clear where it should be, blurry behind, but just not very interesting...</td>', 'well taken, clear where it should be, blurry behind, but just not very interesting...', '2004-03-31 10:04:01.000000', NULL, 1),
