(645599, 66962, 17166, '<td valign="top">Great idea very well executed.  My favorite of the challenge so far.  Wish the shadow on the sitting nickel wasn''t quite so dark so that you could see the edge all the way around.</td>', 'Great idea very well executed.  My favorite of the challenge so far.  Wish the shadow on the sitting nickel wasn''t quite so dark so that you could see the edge all the way around.', '2004-03-31 12:05:00.000000', NULL, 1),
(645606, 66690, 17166, '<td valign="top">I like this - the lines and subtle blur of the people work together to create a feeling of motion.  Lots of noise, though - could stand to take a pass through NeatImage.</td>', 'I like this - the lines and subtle blur of the people work together to create a feeling of motion.  Lots of noise, though - could stand to take a pass through NeatImage.', '2004-03-31 12:08:59.000000', NULL, 1),
(645645, 67169, 2170, '<td valign="top">the border here detracts, as it is not a solid black line.  looks a little sloppy.</td>', 'the border here detracts, as it is not a solid black line.  looks a little sloppy.', '2004-03-31 12:30:17.000000', NULL, 1),
(645646, 67112, 2170, '<td valign="top">awesome shot.  too bad it''s so small.</td>', 'awesome shot.  too bad it''s so small.', '2004-03-31 12:30:29.000000', NULL, 1),
(645647, 66970, 2170, '<td valign="top">love the color, but this seems almost more like an abstract.</td>', 'love the color, but this seems almost more like an abstract.', '2004-03-31 12:30:57.000000', NULL, 1),
