(653689, 67180, 15407, '<td valign="top">Thank You for your comments and votes. Perhaps I would have scored better using a few other pictures that I''m posting in my portfolio?</td>', 'Thank You for your comments and votes. Perhaps I would have scored better using a few other pictures that I''m posting in my portfolio?', '2004-04-05 02:22:49.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(653691, 66970, 6349, '<td valign="top">I think you had the most 10''s with 26 so I find it unreal that you only got 6th place.  I guess some people loved it and some people just don''t like this kind of thing.  I like this kind of thing.  Excellent work.</td>', 'I think you had the most 10''s with 26 so I find it unreal that you only got 6th place.  I guess some people loved it and some people just don''t like this kind of thing.  I like this kind of thing.  Excellent work.', '2004-04-05 02:26:49.000000', NULL, 0),
(653699, 67003, 16046, '<td valign="top">Thought it should have scored higher, nice work again.</td>', 'Thought it should have scored higher, nice work again.', '2004-04-05 02:43:21.000000', NULL, 0),
(653701, 67003, 4338, '<td valign="top">thanks all, I was not very please with the pic, but it was MUCH better than my other hopefuls or the challenge<br/> <br/>James</td>', 'thanks all, I was not very please with the pic, but it was MUCH better than my other hopefuls or the challenge James', '2004-04-05 02:44:44.000000', NULL, 0),
(653814, 67039, 4008, '<td valign="top">Amazed this one did not finish higher, it was in my top 5. One of the more original idea''s and certainly well executed, with good expression and good colors, a clear message. Could be used in an advertisement for headache pills.</td>', 'Amazed this one did not finish higher, it was in my top 5. One of the more original idea''s and certainly well executed, with good expression and good colors, a clear message. Could be used in an advertisement for headache pills.', '2004-04-05 03:22:10.000000', NULL, 0),
(653888, 67124, 9763, '<td valign="top">I would like to thank everyone for their votes!  There was a slight breeze, but I guess it''s hard to tell.  Anyhow, I appreciated your comments and will put them to good use!  :)</td>', 'I would like to thank everyone for their votes!  There was a slight breeze, but I guess it''s hard to tell.  Anyhow, I appreciated your comments and will put them to good use!  :)', '2004-04-05 04:26:03.000000', NULL, 0),
(653913, 66425, 5792, '<td valign="top">Congrats on the coveted "green" ribbon. :) I am disappointed I did not comment on it during the challenge after I finished voting, but I felt this was the overall "best". It is technically superior to almost all others, it has a great perspective and your method of using zoom gives you complete control yet it is simple and very creative. No luck involved here. Kudos to you for a great shot.</td>', 'Congrats on the coveted "green" ribbon. :) I am disappointed I did not comment on it during the challenge after I finished voting, but I felt this was the overall "best". It is technically superior to almost all others, it has a great perspective and your method of using zoom gives you complete control yet it is simple and very creative. No luck involved here. Kudos to you for a great shot.', '2004-04-05 05:06:52.000000', NULL, 0),
(653919, 66984, 5792, '<td valign="top">Congratulations on your blue ribbon. It is about time. In my opinion your image "Umm... Yeah, sure you can ride for free..." from the flight challenge is one of the best images ever posted at DPC and should have been a blue ribbon winner itself.</td>', 'Congratulations on your blue ribbon. It is about time. In my opinion your image "Umm... Yeah, sure you can ride for free..." from the flight challenge is one of the best images ever posted at DPC and should have been a blue ribbon winner itself.', '2004-04-05 05:11:52.000000', NULL, 0),
(653929, 67016, 5792, '<td valign="top">Congratulations on your ribbon. This is the quintessential bike racer motion blur shot. Perfect focus on the entire rider and bike and it is top notch technical quality. This is front cover material for any racing magazine. It amazes how well you captured that at 1/60th.</td>', 'Congratulations on your ribbon. This is the quintessential bike racer motion blur shot. Perfect focus on the entire rider and bike and it is top notch technical quality. This is front cover material for any racing magazine. It amazes how well you captured that at 1/60th.', '2004-04-05 05:18:00.000000', NULL, 0),
(653935, 67133, 5792, '<td valign="top">The jaggies in an image are always bothersome to me and I would have prefered a solid black background, but your concept, framing and capture makes this an outstanding image.</td>', 'The jaggies in an image are always bothersome to me and I would have prefered a solid black background, but your concept, framing and capture makes this an outstanding image.', '2004-04-05 05:23:06.000000', NULL, 0),
(653943, 67064, 5792, '<td valign="top">The guy controlling the action is in generally sharp focus and the motion in the image emphasizes how everyone else is reacting to him. That is what makes this a great "motion blur" image. The croping of this one, whether done in camera or post processing is tremendous. Super capture.</td>', 'The guy controlling the action is in generally sharp focus and the motion in the image emphasizes how everyone else is reacting to him. That is what makes this a great "motion blur" image. The croping of this one, whether done in camera or post processing is tremendous. Super capture.', '2004-04-05 05:30:29.000000', NULL, 0),
(653951, 66638, 5792, '<td valign="top">The way color was processed in this image gives it a surrealistic quality that perfectly supports the accident scene as the main subject. It gives the viewer that "been there, feel for you" reaction. The quality of this image is outstanding and is a wonderful variation of the "streaking car headlights on the freeway" cliche. It is one of my personal top three for this challenge.</td>', 'The way color was processed in this image gives it a surrealistic quality that perfectly supports the accident scene as the main subject. It gives the viewer that "been there, feel for you" reaction. The quality of this image is outstanding and is a wonderful variation of the "streaking car headlights on the freeway" cliche. It is one of my personal top three for this challenge.', '2004-04-05 05:41:05.000000', NULL, 0),
(653952, 67047, 10047, '<td valign="top">Dibutil, Thanks for your comments. The motion blur wasn''t as obvious as I wanted, and I didn''t like the background either, but I liked everything else about the picture, so I submitted. I think I''m going to try some different things with the background and maybe have it printed as a keeper.  My performance for Feb and Mar is a bit inconsistent, but I think is starting to stabilize. I have three photos in challenges right now and two are 6.3+ and the other is still above my current average. Thanks again.</td>', 'Dibutil, Thanks for your comments. The motion blur wasn''t as obvious as I wanted, and I didn''t like the background either, but I liked everything else about the picture, so I submitted. I think I''m going to try some different things with the background and maybe have it printed as a keeper.  My performance for Feb and Mar is a bit inconsistent, but I think is starting to stabilize. I have three photos in challenges right now and two are 6.3+ and the other is still above my current average. Thanks again.', '2004-04-05 05:46:16.000000', NULL, 0),
(653953, 66984, 18709, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by obstetrify:</b></div><hr/><i> Very well caught. </i></td></tr></table></td>', 'Originally posted by obstetrify: Very well caught. ', '2004-04-05 05:48:10.000000', NULL, 0),
