(653958, 67133, 8139, '<td valign="top">Congrats for your well deserved ribbon. Your photo was one of my favorites.</td>', 'Congrats for your well deserved ribbon. Your photo was one of my favorites.', '2004-04-05 05:53:49.000000', NULL, 0),
(653959, 66669, 5792, '<td valign="top">This is one of my personal top three images for this challenge. The profiles of the runners are captured perfectly and this image nicely conveys to the viewer that it takes intensity to achieve success. Perhaps there is a dose of sentimentality for me in it. I competed in track and cross country for many years and vividly remember training.</td>', 'This is one of my personal top three images for this challenge. The profiles of the runners are captured perfectly and this image nicely conveys to the viewer that it takes intensity to achieve success. Perhaps there is a dose of sentimentality for me in it. I competed in track and cross country for many years and vividly remember training.', '2004-04-05 05:55:23.000000', NULL, 0),
